import { createSignal, For, type Component, type ParentComponent } from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import { Filigree } from "#core/ui-next/components/filigree.jsx";
import { Header } from "#core/ui-next/components/header.jsx";
import { HeroButton } from "#core/ui-next/components/hero-button.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { RadioButton, RadioButtonSize } from "#core/ui-next/components/radio-button.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { HSlot, VSlot } from "#core/ui-next/components/slot.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { SandboxBox } from "#core/ui-next/sandbox/sandbox-box.jsx";

export interface ComponentBoxProps {
	name: string;
}

export interface ExtensionProps {
	name: string;
}
const ComponentBox: ParentComponent<ComponentBoxProps> = (props) => {
	return (
		<SandboxBox class="flex flex-col justify-start items-center flex-auto">
			<Header class="mb-2">{props.name}</Header>
			{props.children}
		</SandboxBox>
	);
};

export const ComponentsExample: Component = () => {
	const [hotkeyTriggers, setHotkeyTriggers] = createSignal(0);
	const [buttonsClicked, setButtonsClicked] = createSignal(0);
	const [pipChecked, setPipChecked] = createSignal(false);
	const [listLength, setListLength] = createSignal(200);

	return (
		<ScrollArea class="flex-auto m-4">
			<div class="flex flex-row flex-wrap">
				<ComponentBox name="Stats">
					<span>Buttons Clicked: {buttonsClicked()}</span>
					<span>Hotkey Triggers: {hotkeyTriggers()}</span>
				</ComponentBox>
				<ComponentBox name="Button">
					<Button onActivate={() => setButtonsClicked((n) => n + 1)}>Button</Button>
				</ComponentBox>
				<ComponentBox name="Hero Button">
					<HeroButton onActivate={() => setButtonsClicked((n) => n + 1)}>Hero Button</HeroButton>
				</ComponentBox>
				<ComponentBox name="Header">
					<Header>Header</Header>
				</ComponentBox>
				<ComponentBox name="Filigree.H1">
					<Filigree.H1 />
				</ComponentBox>
				<ComponentBox name="Filigree.H2">
					<Filigree.H2 />
				</ComponentBox>
				<ComponentBox name="Filigree.H3">
					<Filigree.H3 />
				</ComponentBox>
				<ComponentBox name="Filigree.H4">
					<Filigree.H4>H4</Filigree.H4>
				</ComponentBox>
				<ComponentBox name="Filigree.Small">
					<Filigree.Small />
				</ComponentBox>
				<ComponentBox name="Icon">
					LEADER_BENJAMIN_FRANKLIN
					<Icon
						name="LEADER_BENJAMIN_FRANKLIN"
						class="size-24"
					/>
				</ComponentBox>
				<ComponentBox name="L10n Compose">
					LOC_LEADER_BENJAMIN_FRANKLIN_NAME
					<L10n.Compose text="LOC_LEADER_BENJAMIN_FRANKLIN_NAME" />
				</ComponentBox>
				<ComponentBox name="L10n Stylize">
					LOC_TRAIT_LEADER_BENJAMIN_FRANKLIN_ABILITY_DESCRIPTION
					<L10n.Stylize text="LOC_TRAIT_LEADER_BENJAMIN_FRANKLIN_ABILITY_DESCRIPTION" />
				</ComponentBox>
				<ComponentBox name="L10n Stylize Broken Test">
					There should be nothing after this line:
					<L10n.Stylize text="" />
				</ComponentBox>
				<ComponentBox name="Hotkey With NavHelp">
					<Activatable
						name="NavHelp"
						hotkeyAction="shell-action-1"
						disableFocus={true}
						onActivate={() => setHotkeyTriggers((n) => n + 1)}
					>
						<NavHelp class="size-16" />
					</Activatable>
				</ComponentBox>
				<ComponentBox name="Hotkey With NavTray">
					<Activatable
						name="NavTray"
						hotkeyAction="shell-action-2"
						navTrayText="Activate Hotkey"
						disableFocus={true}
						onActivate={() => setHotkeyTriggers((n) => n + 1)}
					/>
					<div class="relative w-64 h-16">
						<nav-tray />
					</div>
				</ComponentBox>
				<ComponentBox name="Radio Button">
					<div class="flex flex-row items-center mb-4">
						Normal:&nbsp;
						<RadioButton
							isChecked={pipChecked()}
							onActivate={() => {
								setPipChecked((v) => !v);
								setButtonsClicked((n) => n + 1);
							}}
						/>
					</div>

					<div class="flex flex-row items-center">
						Large:&nbsp;
						<RadioButton
							size={RadioButtonSize.LARGE}
							isChecked={pipChecked()}
							onActivate={() => {
								setPipChecked((v) => !v);
								setButtonsClicked((n) => n + 1);
							}}
						/>
					</div>
				</ComponentBox>
				<ComponentBox name="Scroll Area">
					<ScrollArea
						class="h-36 flex-auto"
						minThumbHeight={30}
					>
						<For each={Array.from({ length: listLength() })}>{(_, index) => <span>#{index()}</span>}</For>
					</ScrollArea>
					<HSlot>
						<Button
							class="m-2 min-w-32"
							onActivate={() => setListLength(200)}
						>
							200
						</Button>
						<Button
							class="m-2 min-w-32"
							onActivate={() => setListLength(0)}
						>
							0
						</Button>
					</HSlot>
				</ComponentBox>
				<ComponentBox name="HSlot">
					<HSlot>
						<Button
							class="m-2 min-w-32"
							onActivate={() => setButtonsClicked((n) => n + 1)}
						>
							1
						</Button>
						<Button
							class="m-2 min-w-32"
							onActivate={() => setButtonsClicked((n) => n + 1)}
						>
							2
						</Button>
						<Button
							class="m-2 min-w-32"
							onActivate={() => setButtonsClicked((n) => n + 1)}
						>
							3
						</Button>
					</HSlot>
				</ComponentBox>
				<ComponentBox name="VSlot">
					<VSlot>
						<Button
							class="m-2"
							onActivate={() => setButtonsClicked((n) => n + 1)}
						>
							1
						</Button>
						<Button
							class="m-2"
							onActivate={() => setButtonsClicked((n) => n + 1)}
						>
							2
						</Button>
						<Button
							class="m-2"
							onActivate={() => setButtonsClicked((n) => n + 1)}
						>
							3
						</Button>
					</VSlot>
				</ComponentBox>
				<ComponentBox name="Tab (Default)">
					<Tab class="w-full">
						<Tab.TabList />
						<div class="mt-8 flex flex-row flex-auto items-center justify-center">
							<Tab.Output />
						</div>
						<Tab.Item
							name="Tab 1"
							title={() => <Header>"Tab 1"</Header>}
							body={() => "Tab 1 Contents"}
						/>
						<Tab.Item
							name="Tab 2"
							title={() => "Tab 2"}
							body={() => "Tab 2 Contents"}
						/>
						<Tab.Item
							name="Tab 3"
							title={() => "Tab 3"}
							body={() => "Tab 3 Contents"}
						/>
					</Tab>
				</ComponentBox>
				<ComponentBox name="Tab (Pips)">
					<Tab class="w-full">
						<div class="mt-8 flex flex-row flex-auto items-center justify-center">
							<Tab.Output />
						</div>
						<Tab.TabListPips class="items-center justify-center" />
						<Tab.Item
							name="Tab 1"
							title={() => "Tab 1"}
							body={() => "Tab 1 Contents"}
						/>
						<Tab.Item
							name="Tab 2"
							title={() => "Tab 2"}
							body={() => "Tab 2 Contents"}
						/>
						<Tab.Item
							name="Tab 3"
							title={() => "Tab 3"}
							body={() => "Tab 3 Contents"}
						/>
					</Tab>
				</ComponentBox>
				<ComponentBox name="Tooltip">
					<Tooltip>
						<Tooltip.Trigger>
							<Activatable
								class="p-3"
								style={{ border: "1px solid gray" }}
							>
								Hover Me
							</Activatable>
						</Tooltip.Trigger>
						<Tooltip.Content>
							<SandboxBox>
								<Filigree.H1 class="-my-9 -mx-14" />
								<Filigree.H4>
									<Header>I am a fancy tooltip</Header>
								</Filigree.H4>
								<SandboxBox class="flex flex-row items-center">With different sections</SandboxBox>
								<Tooltip.Text text="Inner Tooltip">
									<Button>And A Button</Button>
								</Tooltip.Text>
							</SandboxBox>
						</Tooltip.Content>
					</Tooltip>
				</ComponentBox>
				<ComponentBox name="Text Tooltip">
					<Tooltip.Text text="I am a boring text tooltip">
						<Activatable
							class="p-3"
							style={{ border: "1px solid gray" }}
						>
							Hover Me
						</Activatable>
					</Tooltip.Text>
				</ComponentBox>
			</div>
		</ScrollArea>
	);
};
